      "heroSummary": "以马德里为交通中心，分别向南抵达托莱多的塔霍河环抱古城，向西北进入塞戈维亚的高原石堡与罗马引水工程。马德里提供王室宫殿、迁建古埃及神庙及世界遗产历史园林；托莱多强调河曲、城墙和密集宗教建筑；塞戈维亚则以无砂浆花岗岩水道桥和悬于石灰岩岬角上的城堡形成纵深鲜明的高原景观。塞戈维亚城堡常被视为迪士尼童话城堡的灵感来源之一，但其与白雪公主城堡之间的具体创作关系不宜表述为已证实的唯一原型。坐标参考OpenStreetMap、Mapcarta及官方旅游资料。",
